import re, unicodedata
import pandas as pd, numpy as np

def _h_norm(s):
    s = unicodedata.normalize('NFD', str(s)).encode('ascii', 'ignore').decode().lower()
    return re.sub('\\s+', ' ', s).strip()

def _h_money(s):
    """Parse Vietnamese money strings ('240,000', '45k', '1,45tr')."""
    if isinstance(s, (int, float, np.integer, np.floating)) and (not isinstance(s, bool)):
        return float(s)
    s = str(s).strip().lower().replace('đ', '').replace('₫', '')
    if not s or s in ('nan', 'none'):
        return np.nan
    s = s.replace(' ', '')
    mult = 1.0
    if 'tr' in s:
        mult = 1000000.0
        s = s.replace('tr', '')
        if ',' in s and '.' not in s:
            s = s.replace(',', '.')
        s = s.replace(',', '')
    elif s.endswith('k'):
        mult = 1000.0
        s = s[:-1]
        if ',' in s and '.' not in s:
            s = s.replace(',', '.')
        s = s.replace(',', '')
    else:
        s = s.replace(',', '') if s.count(',') else s
    s = re.sub('[^0-9.\\-]', '', s)
    if s in ('', '-', '.'):
        return np.nan
    try:
        return float(s) * mult
    except Exception:
        return np.nan

def _h_mnum(col):
    return pd.Series(col).map(_h_money)

def _h_dates(col):
    """Parse dates incl. Vietnamese '1 thg 1 2025', dd/mm/yyyy, ISO, Excel serial."""
    s = pd.Series(col)
    if pd.api.types.is_datetime64_any_dtype(s):
        return s
    out = pd.Series(pd.NaT, index=s.index, dtype='datetime64[ns]')
    num = pd.to_numeric(s, errors='coerce')
    mask = num.notna() & (num > 1000) & (num < 100000)
    if mask.any():
        out.loc[mask] = pd.Timestamp('1899-12-30') + pd.to_timedelta(num.loc[mask], unit='D')
    rest = s.notna() & ~mask
    if rest.any():
        t = s.loc[rest].astype(str).str.strip()
        t = t.str.replace('\\s*thg\\s*', '/', regex=True)
        t = t.str.replace('\\s*tháng\\s*', '/', regex=True)
        t = t.str.replace('\\s*-\\s*', '-', regex=True)
        parts = t.str.extract('^(\\d{1,4})[-/](\\d{1,2})[-/](\\d{1,4})')
        parsed = pd.Series(pd.NaT, index=t.index, dtype='datetime64[ns]')
        okp = parts.notna().all(axis=1)
        if okp.any():
            (a, bb, c) = (parts.loc[okp, 0], parts.loc[okp, 1], parts.loc[okp, 2])
            year = c.where(c.str.len() == 4, a)
            month = bb
            day = a.where(c.str.len() == 4, c)
            parsed.loc[okp] = pd.to_datetime(pd.DataFrame({'year': year.astype(int), 'month': month.astype(int), 'day': day.astype(int)}), errors='coerce')
        if (~okp).any():
            parsed.loc[~okp] = pd.to_datetime(t.loc[~okp], errors='coerce', dayfirst=True)
        out.loc[rest] = parsed
    return out

def _h_biz(biz_id):
    return data

def _h_t111():
    b = _h_biz('biz_111')
    don = b['don_hang'].copy()
    ct = b['chi_tiet_don'].copy()
    sp = b['san_pham'].copy()
    kh = b['khach_hang'].copy()
    tt = b['thanh_toan'].copy()
    don['dt'] = _h_dates(don['NgayBan'])
    st = don['Xử lý'].astype(str).str.strip()
    don['st_norm'] = np.select([st.str.contains('cancelled|cancel|huỷ|hủy', case=False, na=False), st.str.contains('returned|return|trả', case=False, na=False)], ['cancel', 'return'], default='ok')
    don['bill'] = _h_mnum(don['Tổng bill'])
    don['conlai'] = _h_mnum(don['Còn lại'])
    ct['ttien'] = _h_mnum(ct['T.Tiền'])
    ct['slqd'] = pd.to_numeric(ct['SL quy đổi'], errors='coerce')
    ct['gia'] = _h_mnum(ct['Giá đơn vị'])
    sp['name_n'] = sp['Sản phẩm'].map(_h_norm)
    sp['size'] = sp['Sản phẩm'].str.extract('\\(([ML])\\)$', flags=re.I)[0].str.upper()
    tt['dt'] = _h_dates(tt['Thời gian thu'])
    tt['tien'] = _h_mnum(tt['Tiền'])
    return dict(don=don, ct=ct, sp=sp, kh=kh, tt=tt)

def _h_month_mask(dt_series, y, m):
    s = pd.Timestamp(year=y, month=m, day=1)
    e = s + pd.offsets.MonthBegin(1)
    return (dt_series >= s) & (dt_series < e)

